// This is used to calculate the debt interests
module protocol::borrow_index;

use math::float::{Self, Decimal};

public struct BorrowIndex has copy, drop, store {
    value: Decimal,
    last_updated: u64,
}

public(package) fun new(
    now: u64,
): BorrowIndex {
    BorrowIndex {
        value: float::one(),
        last_updated: now,
    }
}

public(package) fun set_value(
    self: &mut BorrowIndex,
    value: Decimal,
    now: u64,
) {
    assert!(self.value.le(value), protocol::error::borrow_index_value_going_backwards());
    assert!(self.last_updated <= now, protocol::error::borrow_index_time_going_backwards());

    self.last_updated = now;
    self.value = value;
}

// =============== Getter Functions =============
public(package) fun value(self: &BorrowIndex): Decimal { self.value }
public(package) fun last_updated(self: &BorrowIndex): u64 { self.last_updated }

